-- Seeds seven rooms: a welcome lobby, events plaza, garden lounge, trading floor, games arcade, help center and skyline rooftop.
-- Run it in Adminer against the hotel database. It is safe to run again.
-- Rooms are owned by the oldest account (see @owner). Room images load from @site.
SET @owner = (SELECT MIN(id) FROM users);
SET @site = 'https://retro.steamvaluechecker.com';

DELETE i FROM items i JOIN rooms r ON r.id = i.room_id WHERE r.owner = @owner AND r.model_name IN ('lucado_welcome','lucado_plaza','lucado_garden','lucado_lobby','lucado_trade','lucado_arcade','lucado_help','lucado_roof');
DELETE FROM rooms WHERE owner = @owner AND model_name IN ('lucado_welcome','lucado_plaza','lucado_garden','lucado_lobby','lucado_trade','lucado_arcade','lucado_help','lucado_roof');
DELETE FROM room_models WHERE id IN ('lucado_welcome','lucado_plaza','lucado_garden','lucado_lobby','lucado_trade','lucado_arcade','lucado_help','lucado_roof');

-- Welcome to Lucado Hotel
SET @room = LAST_INSERT_ID();

